import sys

def max_path_length(v1, v2, t, d):
    if v1 == v2:
        return v1 * t

    if v1 < v2:
        # Increasing speed scenario
        max_speed_increase = min(d, v2 - v1)
        full_increments = (v2 - v1) // max_speed_increase
        remaining_time = t - full_increments
        if remaining_time > 0:
            return sum(v1 + i * max_speed_increase for i in range(full_increments)) + (v1 + full_increments * max_speed_increase) * remaining_time
        else:
            return sum(v1 + i * max_speed_increase for i in range(full_increments))
    else:
        # Decreasing speed scenario
        max_speed_decrease = min(d, v1 - v2)
        full_decrements = (v1 - v2) // max_speed_decrease
        remaining_time = t - full_decrements
        if remaining_time > 0:
            return sum(v1 - i * max_speed_decrease for i in range(full_decrements)) + (v1 - full_decrements * max_speed_decrease) * remaining_time
        else:
            return sum(v1 - i * max_speed_decrease for i in range(full_decrements))

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    v1 = int(data[0])
    v2 = int(data[1])
    t = int(data[2])
    d = int(data[3])

    result = max_path_length(v1, v2, t, d)
    print(result)

if __name__ == "__main__":
    main()
